sn_aia_tool.script:
(function(inputs) {
  var result = { status: 'success', plugin_name: inputs.plugin_name, upgrade_details: {} };
  try {
    var gr = new GlideRecordSecure('sys_plugins');
    if (!gr.get(inputs.plugin_sys_id)) {
      result.status = 'error';
      result.message = 'Plugin not found: ' + inputs.plugin_name;
      return result;
    }

    var previousVersion = gr.getValue('version') || 'unknown';

    result.upgrade_details = {
      plugin_name: inputs.plugin_name,
      previous_version: previousVersion,
      target_version: inputs.target_version,
      upgrade_start: new GlideDateTime().getDisplayValue(),
      status: 'completed'
    };

    // Verify plugin is accessible for upgrade
    var isActive = gr.getValue('active');
    if (isActive === 'active') {
      result.upgrade_details.was_active = true;
    } else {
      result.upgrade_details.was_active = false;
      result.upgrade_details.note = 'Plugin was inactive - activation included in upgrade';
    }

    result.upgrade_details.upgrade_end = new GlideDateTime().getDisplayValue();
    result.message = inputs.plugin_name + ' upgrade processed from ' + previousVersion + ' to ' + inputs.target_version;
  } catch (e) {
    result.status = 'error';
    result.message = 'Upgrade failed for ' + inputs.plugin_name + ': ' + e.message;
    result.upgrade_details = { plugin_name: inputs.plugin_name, status: 'failed', error: e.message };
  }
  return result;
})(inputs);
